    case 2: {
        CPersistTraits<T> traits;
        traits.TransferBinaryIn(LoadStream, value);
        break;
    }
    case 3:
        SaveStream->Write3DVector(value);
        break;
    default:
        value = defaultValue;
        break;
    }
}

