void* CPersistTraits::RemoveNodeAndRecycle(SNode* node)
{
    if (!node)
        return 0;
    if (node->prev == 0)
        m_head = node->next;
    else
        node->prev->next = node->next;
    if (node->next == 0)
        m_tail = node->prev;
    else
        node->next->prev = node->prev;
    void* data = node->data;
    if (m_freeCount < m_maxFree) {
        node->next = m_freeList;
        m_freeList = node;
        ++m_freeCount;
    } else {
